application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink: #172033; --muted: #718096; --line: #e5eaf2; --blue: #3867f0; --soft: #f5f7ff; --mint: #dff8ed; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; color: var(--ink); background: #f2f5fa; font-family: 'DM Sans', sans-serif; }
body:before { content: ''; position: fixed; inset: 0 0 auto; height: 330px; z-index: -1; background: linear-gradient(120deg, #dce8ff, #f3eaff 65%, #fff4df); }
.app-shell { width: min(760px, calc(100% - 32px)); margin: 0 auto; padding: 70px 0 55px; }
.hero { text-align: center; margin-bottom: 34px; }
.eyebrow, .result-label { color: var(--blue); font-size: 11px; font-weight: 700; letter-spacing: .18em; }
h1 { margin: 12px 0 10px; font: 700 clamp(34px, 6vw, 52px)/1.05 'Space Grotesk', sans-serif; letter-spacing: -.045em; }
.hero p { margin: 0; color: var(--muted); font-size: 16px; }
.quiz-card { padding: 10px 34px 28px; background: rgba(255,255,255,.94); border: 1px solid rgba(255,255,255,.8); border-radius: 24px; box-shadow: 0 20px 55px rgba(48,68,110,.12); }
.question { padding: 27px 0 29px; border-bottom: 1px solid var(--line); }
.question-heading { display: flex; gap: 16px; align-items: flex-start; }
.question-number { flex: 0 0 auto; display: grid; place-items: center; width: 34px; height: 34px; color: var(--blue); background: var(--soft); border-radius: 10px; font-size: 12px; font-weight: 700; }
h2 { margin: 3px 0 20px; font: 600 19px/1.35 'Space Grotesk', sans-serif; }
.options { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-left: 50px; }
.option { display: flex; align-items: center; gap: 10px; min-height: 48px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 11px; color: #45536b; cursor: pointer; font-size: 14px; transition: .2s ease; }
.option:hover { border-color: #aebff7; background: #fafbff; transform: translateY(-1px); }
.option input { position: absolute; opacity: 0; pointer-events: none; }
.radio-mark { width: 17px; height: 17px; flex: 0 0 17px; border: 2px solid #cbd3e1; border-radius: 50%; position: relative; }
.option:has(input:checked) { color: var(--blue); border-color: var(--blue); background: var(--soft); font-weight: 700; }
.option:has(input:checked) .radio-mark { border-color: var(--blue); }
.option:has(input:checked) .radio-mark:after { content: ''; position: absolute; inset: 3px; border-radius: 50%; background: var(--blue); }
.quiz-footer { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding-top: 25px; }
.status { margin: 0; color: var(--muted); font-size: 13px; }
.status.error { color: #d45d5d; }
button { border: 0; border-radius: 12px; padding: 14px 20px; color: white; background: var(--blue); font: 700 14px 'DM Sans', sans-serif; cursor: pointer; box-shadow: 0 8px 18px rgba(56,103,240,.25); transition: .2s; }
button:hover { background: #2854d6; transform: translateY(-2px); }
button span { margin-left: 9px; font-size: 18px; vertical-align: -1px; }
.result { margin: 25px auto 0; text-align: center; }
.score { margin: 5px 0 1px; font: 700 44px 'Space Grotesk', sans-serif; color: var(--ink); }
.result p { margin: 0; color: var(--muted); font-size: 13px; }
@media (max-width: 620px) { .app-shell { padding-top: 42px; } .quiz-card { padding: 4px 20px 22px; } .options { grid-template-columns: 1fr; margin-left: 0; } .quiz-footer { align-items: stretch; flex-direction: column; } button { width: 100%; } }

application.javascript:
const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const statusElement = document.getElementById('status');
const answers = { q1: 'mars', q2: 'pacific', q3: 'piano' };

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const formData = new FormData(form);
  const unanswered = ['q1', 'q2', 'q3'].filter((question) => !formData.get(question));

  if (unanswered.length) {
    statusElement.textContent = 'Please answer all three questions before submitting.';
    statusElement.classList.add('error');
    return;
  }

  let score = 0;
  Object.keys(answers).forEach((question) => {
    if (formData.get(question) === answers[question]) score += 1;
  });

  scoreElement.textContent = String(score);
  scoreElement.setAttribute('data-score', String(score));
  statusElement.textContent = score === 3 ? 'Perfect score — excellent work!' : 'Your result is ready. Try again to improve it.';
  statusElement.classList.remove('error');
});

form.addEventListener('change', () => {
  statusElement.textContent = 'Choose one answer for each question.';
  statusElement.classList.remove('error');
});
